                    // Check for associated label
                    if (input.id) {
                        field.hasLabel = !!document.querySelector(`label[for="${input.id}"]`);
                    }

                    // Check if wrapped in label
                    if (!field.hasLabel) {
                        field.hasLabel = !!input.closest('label');
                    }

